#include <unistd.h>
#include <sys/inotify.h>
#include <linux/limits.h>
#include <errno.h>
#include <sys/resource.h>

int create_inotify_instance(int flags) {
    // Validate flags against known inotify constants
    if ((flags & ~(IN_CLOEXEC | IN_NONBLOCK)) != 0) {
        errno = EINVAL;
        return -1;
    }

    // Check system and user limits for inotify instances
    struct rlimit rlim;
    if (getrlimit(RLIMIT_INOTIFY_INSTANCES, &rlim) < 0) {
        return -1;
    }

    if (rlim.rlim_cur <= 0) {
        errno = ENOSPC;
        return -1;
    }

    // Attempt to create inotify instance
    int fd = inotify_init1(flags);
    if (fd < 0) {
        return -1;
    }

    return fd;
}

